function solve(freq) {
  const f = [...freq].sort((a, b) => a - b)
  let total = 0
  while (f.length > 1) {
    // Gabungkan dua frekuensi terkecil.
    const gabung = f.shift() + f.shift()
    total += gabung
    // Sisipkan hasilnya agar daftar tetap terurut.
    let i = 0
    while (i < f.length && f[i] < gabung) i++
    f.splice(i, 0, gabung)
  }
  return total
}
